from typing import List


def min_cost_stepping_stones(costs: List[int]) -> int:
    n = len(costs)
    # dp[i] = min cost to stand at position i, where position 0 is the near bank
    # and positions 1..n are stones, n + 1 is the far bank.
    dp = [0] + [float("inf")] * (n + 1)
    for i in range(1, n + 2):
        land = costs[i - 1] if i <= n else 0
        dp[i] = land + min(dp[j] for j in range(max(0, i - 3), i))
    return int(dp[n + 1])

def count_binary_strings_no_adjacent_ones(n: int) -> int:
    if n == 0:
        return 1
    ends_zero, ends_one = 1, 1  # valid strings of length 1
    for _ in range(n - 1):
        ends_zero, ends_one = ends_zero + ends_one, ends_zero
    return ends_zero + ends_one

def count_domino_tilings_2xn(n: int) -> int:
    prev, cur = 1, 1  # tilings of widths 0 and 1
    for _ in range(n - 1):
        prev, cur = cur, prev + cur
    return cur

def count_monotone_grid_routes(rows: int, cols: int) -> int:
    if rows <= 0 or cols <= 0:
        return 0
    row = [1] * cols
    for _ in range(1, rows):
        for c in range(1, cols):
            row[c] += row[c - 1]
    return row[-1]

