def min_triangle_descent(triangle: List[List[int]]) -> int:
    if not triangle:
        return 0
    below = list(triangle[-1])
    for r in range(len(triangle) - 2, -1, -1):
        below = [triangle[r][i] + min(below[i], below[i + 1]) for i in range(r + 1)]
    return below[0]

