def longest_alternating_parity_run(nums: List[int]) -> int:
    best = cur = 0
    for i, x in enumerate(nums):
        if i > 0 and (x - nums[i - 1]) % 2 == 1:
            cur += 1
        else:
            cur = 1
        best = max(best, cur)
    return best

def count_score_combinations(target: int) -> int:
    if target < 0:
        return 0
    ways = [1] + [0] * target
    for points in (3, 5, 10):
        for total in range(points, target + 1):
            ways[total] += ways[total - points]
    return ways[target]

def catalan_by_recurrence(n: int) -> int:
    cat = [1] + [0] * n
    for k in range(1, n + 1):
        cat[k] = sum(cat[i] * cat[k - 1 - i] for i in range(k))
    return cat[n]

def fewest_perfect_squares(n: int) -> int:
    best = [0] + [n] * n
    for total in range(1, n + 1):
        k = 1
        while k * k <= total:
            best[total] = min(best[total], best[total - k * k] + 1)
            k += 1
    return best[n]

