def fewest_coins_for_amount(coins: List[int], amount: int) -> int:
    inf = amount + 1
    best = [0] + [inf] * amount
    for value in range(1, amount + 1):
        for c in coins:
            if c <= value and best[value - c] + 1 < best[value]:
                best[value] = best[value - c] + 1
    return best[amount] if best[amount] < inf else -1

def count_letter_code_decodings(code: str) -> int:
    prev2, prev1 = 1, 1  # ways for prefixes of length i-2 and i-1
    for i in range(1, len(code) + 1):
        cur = 0
        if code[i - 1] != "0":
            cur += prev1
        if i >= 2 and code[i - 2] != "0" and 10 <= int(code[i - 2:i]) <= 26:
            cur += prev2
        prev2, prev1 = prev1, cur
    return prev1

def common_subsequence_length(a: str, b: str) -> int:
    prev = [0] * (len(b) + 1)
    for ch in a:
        cur = [0] * (len(b) + 1)
        for j, other in enumerate(b, start=1):
            cur[j] = prev[j - 1] + 1 if ch == other else max(prev[j], cur[j - 1])
        prev = cur
    return prev[-1]

def insert_delete_distance(source: str, target: str) -> int:
    m, n = len(source), len(target)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0 or j == 0:
                dp[i][j] = i + j
            elif source[i - 1] == target[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(dp[i - 1][j], dp[i][j - 1])
    return dp[m][n]

