def largest_all_ones_square(matrix: List[List[int]]) -> int:
    if not matrix or not matrix[0]:
        return 0
    cols = len(matrix[0])
    prev = [0] * (cols + 1)
    best = 0
    for row in matrix:
        cur = [0] * (cols + 1)
        for c in range(1, cols + 1):
            if row[c - 1] == 1:
                cur[c] = 1 + min(prev[c], prev[c - 1], cur[c - 1])
                best = max(best, cur[c])
        prev = cur
    return best

