def splits_into_equal_sum_groups(weights: List[int]) -> bool:
    total = sum(weights)
    if total % 2:
        return False
    half = total // 2
    reachable = [True] + [False] * half
    for w in weights:
        for s in range(half, w - 1, -1):
            if reachable[s - w]:
                reachable[s] = True
    return reachable[half]

