def count_dictionary_segmentations(text: str, words: List[str]) -> int:
    vocab = {w for w in words if w}
    lengths = sorted({len(w) for w in vocab})
    ways = [1] + [0] * len(text)
    for end in range(1, len(text) + 1):
        for size in lengths:
            if size > end:
                break
            if text[end - size:end] in vocab:
                ways[end] += ways[end - size]
    return ways[len(text)]

def longest_palindromic_subsequence_size(text: str) -> int:
    n = len(text)
    dp = [[0] * n for _ in range(n)]
    for i in range(n - 1, -1, -1):
        dp[i][i] = 1
        for j in range(i + 1, n):
            if text[i] == text[j]:
                dp[i][j] = dp[i + 1][j - 1] + 2
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])
    return dp[0][n - 1] if n else 0

