def richest_right_down_path(grid: List[List[int]]) -> int:
    cols = len(grid[0])
    best = [0] * cols
    for r, row in enumerate(grid):
        for c in range(cols):
            if r == 0 and c == 0:
                best[c] = row[c]
            elif r == 0:
                best[c] = best[c - 1] + row[c]
            elif c == 0:
                best[c] = best[c] + row[c]
            else:
                best[c] = max(best[c], best[c - 1]) + row[c]
    return best[-1]

def count_integer_partitions(n: int) -> int:
    if n < 0:
        return 0
    ways = [1] + [0] * n
    for part in range(1, n + 1):
        for total in range(part, n + 1):
            ways[total] += ways[total - part]
    return ways[n]

def fence_colorings_no_triple(posts: int, colors: int) -> int:
    if posts <= 0 or colors <= 0:
        return 0
    same, diff = 0, colors  # last two equal / last two different
    for _ in range(posts - 1):
        same, diff = diff, (same + diff) * (colors - 1)
    return same + diff

def fewest_cuts_into_palindromes(text: str) -> int:
    n = len(text)
    if n == 0:
        return 0
    is_pal = [[False] * n for _ in range(n)]
    cuts = [0] * n
    for end in range(n):
        best = end
        for start in range(end + 1):
            if text[start] == text[end] and (end - start < 2 or is_pal[start + 1][end - 1]):
                is_pal[start][end] = True
                best = 0 if start == 0 else min(best, cuts[start - 1] + 1)
        cuts[end] = best
    return cuts[n - 1]

def glob_pattern_matches(text: str, pattern: str) -> bool:
    n = len(text)
    prev = [True] + [False] * n
    for p in pattern:
        cur = [False] * (n + 1)
        if p == "*":
            cur[0] = prev[0]
            for j in range(1, n + 1):
                cur[j] = prev[j] or cur[j - 1]
        else:
            for j in range(1, n + 1):
                cur[j] = prev[j - 1] and (p == "?" or p == text[j - 1])
        prev = cur
    return prev[n]

