def max_gain_with_trade_limit(prices: List[int], max_trades: int) -> int:
    if not prices or max_trades <= 0:
        return 0
    if max_trades >= len(prices) // 2:
        return sum(max(0, b - a) for a, b in zip(prices, prices[1:]))
    holding = [float("-inf")] * (max_trades + 1)
    free = [0] * (max_trades + 1)
    for p in prices:
        for t in range(1, max_trades + 1):
            holding[t] = max(holding[t], free[t - 1] - p)
            free[t] = max(free[t], holding[t] + p)
    return free[max_trades]

def count_subsequence_embeddings(source: str, pattern: str) -> int:
    m = len(pattern)
    ways = [1] + [0] * m
    for ch in source:
        for j in range(m, 0, -1):
            if pattern[j - 1] == ch:
                ways[j] += ways[j - 1]
    return ways[m]

def longest_balanced_paren_span(text: str) -> int:
    n = len(text)
    span = [0] * n  # longest balanced substring ending at index i
    best = 0
    for i in range(1, n):
        if text[i] != ")":
            continue
        if text[i - 1] == "(":
            span[i] = 2 + (span[i - 2] if i >= 2 else 0)
        else:
            j = i - span[i - 1] - 1
            if j >= 0 and text[j] == "(":
                span[i] = span[i - 1] + 2 + (span[j - 1] if j >= 1 else 0)
        best = max(best, span[i])
    return best

